    @OACalculatedProperty(displayName = "Total Days", description = "based on all of the items for the order", displayLength = 3, columnLength = 10, properties = {P_OrderItems+"."+OrderItem.P_CalcMinimumDays})
    public int getCalcMinimumDays() {
        Hub h = getOrderItems();
        int max = 0;
        for (int i=0; ;i++) {
            OrderItem oi = (OrderItem) h.getAt(i);
            if (oi == null) break;
            max = Math.max(max, oi.getCalcMinimumDays());
        }
        return max;
    }
    @OACalculatedProperty(displayName = "Flags", displayLength = 5, properties = {P_Notes, P_OrderNotes+"."+OrderNote.P_Note, P_ShipTo+"."+ShipTo.P_Notes, P_ShipTo+"."+ShipTo.P_Instructions})
    public String getCalcFlags() {
        String flag = "";
        
        Hub h = getOrderNotes();
        for (int i=0; ;i++) {
            OrderNote note = (OrderNote) h.getAt(i);
            if (note == null) break;
            String s = note.getNote();
            if (s != null && s.length() > 0) {
                flag += "N";
                break;
            }
        }
        
        ShipTo st = getShipTo();
        if (st != null) {
            String s = st.getInstructions();
            if (s != null && s.length() > 0) {
                if (flag.length() > 0) flag+=",";
                flag += "I";
            }
            s = st.getNotes();
            if (s != null && s.length() > 0) {
                if (flag.length() > 0) flag+=",";
                flag += "Sn";
            }
        }
        return flag; 
    }
    @OACalculatedProperty(displayName = "Total Weight", displayLength = 5, columnLength = 9, properties = {P_OrderItems+"."+OrderItem.P_Quantity, P_OrderItems+"."+OrderItem.P_Item+"."+Item.P_Weight})
    public int getCalcTotalWeight() {
        Hub<OrderItem> hub = getOrderItems();
        int tot = 0;
        for (OrderItem oi : hub) {
            int q = oi.getQuantity();
            if (q == 0) continue;
            Item item = oi.getItem();
            if (item == null) continue;
            tot += q * item.getWeight();
        }
        return tot;
    }
    @OACalculatedProperty(displayName = "Delivery Charge", decimalPlaces = 2, isCurrency = true, displayLength = 9, columnName = "Dlvr Chrg", properties = {P_OrderItems+"."+OrderItem.P_Item+"."+Item.P_Code})
    public double getCalcDeliveryCharge() {
        for (OrderItem oi : getOrderItems()) {
            Item item = oi.getItem();
            if (item != null && "99050020".equals(item.getCode()) ) {
                return oi.getExtendedAmount();
            }
        }
        return 0.0;
    }
    @OACalculatedProperty(displayName = "Is Valid Quantity", displayLength = 2, columnLength = 12, columnName = "Is Valid Qty", properties = {P_OrderItems+"."+OrderItem.P_IsValidQuantity})
    public boolean getIsValidQuantity() {
        for (OrderItem oi : getOrderItems()) {
            if (!oi.getIsValidQuantity()) return false;
        }
        return true;
    }
    @OACalculatedProperty(displayName = "Is Valid", displayLength = 2, columnLength = 8, properties = {P_IsValidQuantity, P_DateCompleted, P_DeleteDate})
    public boolean getIsValid() {
        if (this.getDateCompleted() != null) return true;
        if (this.getDeleteDate() != null) return true;;
        boolean b = this.getIsValidQuantity();
        return b;
    }
    @OACalculatedProperty(displayName = "Payment Status", displayLength = 6, columnLength = 10, properties = {P_Customer+"."+Customer.P_CurrentBalance, P_TotalPrice})
    public int getCalcPaymentStatus() {
        int result = Order.PAYMENTSTATUS_UNPAID;
        Customer customer = this.getCustomer();
        if (customer == null) return result;
        double balance = customer.getCurrentBalance();
    
        double orderTotal = this.getTotalPrice();
        int x = OAConv.compare(balance, orderTotal, 2);
    
        if (x == 0) result = Order.PAYMENTSTATUS_PAID;
        else if (balance >  0) result = Order.PAYMENTSTATUS_PARTIAL;
        else result = Order.PAYMENTSTATUS_UNPAID;
        return result;
    }
    public static final int PAYMENTSTATUS_UNPAID = 0;
    public static final int PAYMENTSTATUS_PARTIAL = 1;
    public static final int PAYMENTSTATUS_PAID = 2;
    public static final Hub<String> hubPaymentStatus;
    static {
        hubPaymentStatus = new Hub<String>(String.class);
        hubPaymentStatus.addElement("Unpaid");
        hubPaymentStatus.addElement("Partial");
        hubPaymentStatus.addElement("Paid");
    }
    @OACalculatedProperty(displayName = "Unshipped Price", decimalPlaces = 2, isCurrency = true, displayLength = 9, columnLength = 15, properties = {P_OrderItems+"."+OrderItem.P_UnshippedPrice})
    public double getRemainingPrice() {
        return getUnshippedPrice();
    }
    public double getUnshippedPrice() {
        double d = 0;
        Hub<OrderItem> hubOrderItems = this.getOrderItems();
        for (OrderItem orderItem : hubOrderItems) {
            d += orderItem.getUnshippedPrice();
        }
        return d;
    }
    @OACalculatedProperty(displayName = "Calc Scheduled End Date", displayLength = 8, columnLength = 23, properties = {P_WorkOrders+"."+WorkOrder.P_ScheduledEndDate})
    public OADate getCalcScheduledEndDate() {
        OADate date = null;
        for (WorkOrder workOrder : getWorkOrders()) {
            OADate d = workOrder.getScheduledEndDate();
            if (d != null && (date == null || d.before(date))) date = d;
        }
        return date;
    }

