    @OAMany(
        displayName = "Work Orders", 
        toClass = WorkOrder.class, 
        owner = true, 
        reverseName = WorkOrder.P_Order, 
        isProcessed = true, 
        cascadeSave = true, 
        cascadeDelete = true, 
        sortProperty = WorkOrder.P_Id
    )
    public Hub<WorkOrder> getWorkOrders() {
        if (hubWorkOrders == null) {
            hubWorkOrders = (Hub<WorkOrder>) getHub(P_WorkOrders);
            if (isServer()) {
                hubWorkOrders.addHubListener(new HubListenerAdapter<WorkOrder>() {
                    @Override
                    public void afterAdd(HubEvent e) {
                        updateWorkOrders();
                    }
                    @Override
                    public void afterInsert(HubEvent e) {
                        updateWorkOrders();
                    }
                    @Override
                    public void afterRemove(HubEvent e) {
                        updateWorkOrders();
                    }
                    @Override
                    public void onNewList(HubEvent e) {
                        updateWorkOrders();
                    }
                });
                updateWorkOrders();
            }
        }
        return hubWorkOrders;
    }
    @OAMethod(displayName = "Create Work Order")
    public void createWorkOrder() {
        // use this to run on server (remote)
        if (isRemoteAvailable()) {
            remote();
            return;
        }
        try {
            sendMessages(true);
            final WorkOrder wo = new WorkOrder();
            wo.setOrder(this);
        }
        finally {
            sendMessages(false);
        }
    }
    @OAObjCallback(enabledProperty = Order.P_DateCompleted, enabledValue = false)
    public void createWorkOrderCallback(OAObjectCallback cb) {
    }

    @OAMethod(displayName = "Update Work Orders")
    public void updateWorkOrders() {
        // use this to run on server (remote)
        if (isRemoteAvailable()) {
            remote();
            return;
        }
        try {
            sendMessages(true);
            _updateWorkOrders();
        }
        finally {
            sendMessages(false);
        }
    }
    private void _updateWorkOrders() {
        for (OrderItem oi : getOrderItems()) {
            int qty = oi.getQuantity();
            for (WorkOrder workOrder : getWorkOrders()) {
                for (WOItem woItem : workOrder.getWOItems()) {
                    if (woItem.getOrderItem() == oi) {
                        qty -= woItem.getQuantity();
                    }
                }
            }
            if (qty < 0) qty = 0;
    
            Item item = oi.getItem();
            if (item != null && item.getIsProduced()) {
                // create missing WOItems
                for (WorkOrder workOrder : getWorkOrders()) {
                    boolean bFound = false;
                    for (WOItem woItem : workOrder.getWOItems()) {
                        if (woItem.getOrderItem() == oi) {
                            bFound = true;
                            break;
                        }
                    }
                    if (!bFound) {
                        WOItem woItem = new WOItem();
                        woItem.setOrderItem(oi);
                        woItem.setWorkOrder(workOrder);
                        woItem.setQuantity(qty);
                        break;
                    }
                }
            }
        }
        // remove WOItems that dont have a valid WorkOrder
        for (WorkOrder workOrder : getWorkOrders()) {
            for (WOItem woItem : workOrder.getWOItems()) {
                OrderItem oi = woItem.getOrderItem();
                boolean bDelete;
                if (oi == null) bDelete = true;
                else {
                    Item item = oi.getItem();
                    bDelete = (item == null) || !item.getIsProduced();
                }
                if (bDelete) {
                    woItem.delete();
                }
            }
        }
    }

    public void load(ResultSet rs, int id) throws SQLException {
        this.id = id;
        java.sql.Date date;
        date = rs.getDate(2);
        if (date != null) this.date = new OADate(date);
        this.salesOrderNumber = rs.getString(3);
        this.totalPrice = rs.getDouble(4);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_TotalPrice, rs.wasNull());
        date = rs.getDate(5);
        if (date != null) this.releasedDate = new OADate(date);
        date = rs.getDate(6);
        if (date != null) this.custExpectedDate = new OADate(date);
        date = rs.getDate(7);
        if (date != null) this.expectedShipDate = new OADate(date);
        date = rs.getDate(8);
        if (date != null) this.expectedProductionEndDate = new OADate(date);
        date = rs.getDate(9);
        if (date != null) this.inspectByDate = new OADate(date);
        date = rs.getDate(10);
        if (date != null) this.inspectedDate = new OADate(date);
        date = rs.getDate(11);
        if (date != null) this.dateCompleted = new OADate(date);
        this.customerPickUp = (rs.getShort(12) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_CustomerPickUp, rs.wasNull());
        this.qbListId = rs.getString(13);
        this.notes = rs.getString(14);
        date = rs.getDate(15);
        if (date != null) this.deleteDate = new OADate(date);
        java.sql.Timestamp timestamp;
        timestamp = rs.getTimestamp(16);
        if (timestamp != null) this.lastUpdate = new OADateTime(timestamp);
        this.purchaseOrder = rs.getString(17);
        int colorCodeFkey = rs.getInt(18);
        setFkeyProperty(P_ColorCode, rs.wasNull() ? null : colorCodeFkey);
        int customerFkey = rs.getInt(19);
        setFkeyProperty(P_Customer, rs.wasNull() ? null : customerFkey);
        int regionFkey = rs.getInt(20);
        setFkeyProperty(P_Region, rs.wasNull() ? null : regionFkey);
        int salesOrderFkey = rs.getInt(21);
        setFkeyProperty(P_SalesOrder, rs.wasNull() ? null : salesOrderFkey);
        int shipToFkey = rs.getInt(22);
        setFkeyProperty(P_ShipTo, rs.wasNull() ? null : shipToFkey);
        int textureFkey = rs.getInt(23);
        setFkeyProperty(P_Texture, rs.wasNull() ? null : textureFkey);

        this.changedFlag = false;
        this.newFlag = false;
    }
